/* General Android PRNG contracts. Original AndroSwitch, MIT OR Apache-2.0.
 * Fixed vectors were generated by compiling unchanged API26 NetBSD PRNG
 * sources from AOSP f711b078b9656f7dbb52a046a7f992a450e8fa13, not this
 * provider. Source hashes/reproduction are recorded in
 * reports/m9-native-random-20261024.json. AS_RANDOM_REFERENCE optionally
 * compares further draws with those upstream reference objects. Their full
 * original BSD notices remain in downloaded files.
 */
#include "bionic_random.h"
#include <assert.h>
#include <errno.h>
#include <limits.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
void as_cxx_lock(void) { assert(!pthread_mutex_lock(&mutex)); }
void as_cxx_unlock(void) { assert(!pthread_mutex_unlock(&mutex)); }
static int (*draw)(void);
static long (*draw_long)(void);
static void (*seed_stream)(unsigned);
static void (*seed_long)(unsigned);
static int (*draw_r)(unsigned *);
static const unsigned seeds[] = {0, 1, 42, 0x7fffffff, 0x80000000, 0xffffffff};
static const int vectors[][10] = {
    {2059215011, 2052119187, 2047820401, 968558420, 2033801269, 2028408493,
     2022120753, 2011989735, 931476857, 924298741},
    {1804289383, 846930886, 1681692777, 1714636915, 1957747793, 424238335,
     719885386, 1649760492, 596516649, 1189641421},
    {71876166, 708592740, 1483128881, 907283241, 442951012, 537146758,
     1366999021, 1854614940, 647800535, 53523743},
    {977399425, 2046899839, 966903128, 2032571191, 2027351843, 946434570,
     2010447341, 2003997915, 922023992, 910350580},
    {1336741213, 1210407648, 1447044896, 337392383, 82502902, 538660432,
     1313908778, 370221063, 344413073, 1896089129},
    {254925627, 1205188300, 366127624, 1401405153, 76053476, 1604170158,
     1302235366, 362229243, 334960208, 1882140968}};
#define THREADS 4
#define PER_THREAD 2048
static int expected[THREADS * PER_THREAD], concurrent[THREADS * PER_THREAD];
static pthread_barrier_t start;
static void *worker(void *opaque) {
  size_t index = (size_t)opaque;
  unsigned own_seed = (unsigned)index + 1;
  uint32_t reference = own_seed;
  int result = pthread_barrier_wait(&start);
  assert(!result || result == PTHREAD_BARRIER_SERIAL_THREAD);
  errno = EDOM;
  for (unsigned i = 0; i < PER_THREAD; ++i) {
    concurrent[index * PER_THREAD + i] = i & 1 ? (int)draw_long() : draw();
    reference = reference * UINT32_C(1103515245) + UINT32_C(12345);
    assert(draw_r(&own_seed) == (int)(reference & INT32_MAX) &&
           own_seed == reference);
    assert(errno == EDOM);
  }
  return NULL;
}
static int compare(const void *a, const void *b) {
  int first = *(const int *)a, second = *(const int *)b;
  return (first > second) - (first < second);
}
#ifdef AS_RANDOM_REFERENCE
extern long reference_random(void);
extern void reference_srandom(unsigned);
extern int reference_rand_r(unsigned *);
static void reference_comparison(void) {
  const unsigned extra[] = {0,         1,          2,          42,
                            123456789, 0x7fffffff, 0x80000000, 0xffffffff};
  for (unsigned i = 0; i < sizeof(extra) / sizeof(extra[0]); ++i) {
    seed_stream(extra[i]);
    reference_srandom(extra[i]);
    unsigned a = extra[i], b = a;
    for (unsigned j = 0; j < 10000; ++j) {
      assert((j & 1 ? draw_long() : draw()) == reference_random());
      assert(draw_r(&a) == reference_rand_r(&b) && a == b);
    }
  }
  puts("pinned API26 upstream oracle: PASS (80000 shared draws + 80000 rand_r "
       "draws)");
}
#endif
int main(void) {
  draw = (void *)as_bionic_random_import("rand");
  draw_long = (void *)as_bionic_random_import("random");
  seed_stream = (void *)as_bionic_random_import("srand");
  seed_long = (void *)as_bionic_random_import("srandom");
  draw_r = (void *)as_bionic_random_import("rand_r");
  assert(draw && draw_long && seed_stream && seed_long && draw_r);
  assert(!as_bionic_random_import("initstate") &&
         !as_bionic_random_import("setstate"));
  assert(draw() == vectors[1][0]); /* unseeded default */
  errno = E2BIG;
  for (unsigned s = 0; s < sizeof(seeds) / sizeof(seeds[0]); ++s) {
    seed_stream(seeds[s]);
    for (unsigned i = 0; i < 10; ++i)
      assert((i & 1 ? draw_long() : draw()) == vectors[s][i]);
    seed_long(seeds[s]);
    for (unsigned i = 0; i < 10; ++i)
      assert(draw() == vectors[s][i]);
    assert(errno == E2BIG);
  }
  const int expected_r[] = {1103527590, 377401575, 662824084,  1147902781,
                            2035015474, 368800899, 1508029952, 486256185,
                            1062517886, 267834847};
  unsigned caller_seed = 1;
  for (unsigned i = 0; i < 10; ++i)
    assert(draw_r(&caller_seed) == expected_r[i]);
  assert(caller_seed == 267834847 && errno == E2BIG);
  /* Guest rand_r does not advance the guest shared stream. */
  seed_stream(1);
  assert(draw() == vectors[1][0]);
  for (unsigned i = 0; i < 100; ++i)
    (void)draw_r(&caller_seed);
  assert(draw() == vectors[1][1]);
  /* Guest functions never seed/advance the host's stream. */
  int host_values[3];
  srand(7654);
  for (unsigned i = 0; i < 3; ++i)
    host_values[i] = rand();
  srand(7654);
  seed_stream(123);
  for (unsigned i = 0; i < 100; ++i)
    (void)draw();
  for (unsigned i = 0; i < 3; ++i)
    assert(rand() == host_values[i]);
  seed_stream(42);
  for (unsigned i = 0; i < THREADS * PER_THREAD; ++i)
    expected[i] = draw();
  int after = draw();
  seed_long(42);
  assert(!pthread_barrier_init(&start, NULL, THREADS));
  pthread_t workers[THREADS];
  for (size_t i = 0; i < THREADS; ++i)
    assert(!pthread_create(&workers[i], NULL, worker, (void *)i));
  for (unsigned i = 0; i < THREADS; ++i)
    assert(!pthread_join(workers[i], NULL));
  assert(!pthread_barrier_destroy(&start));
  assert(draw() == after);
  qsort(expected, THREADS * PER_THREAD, sizeof(int), compare);
  qsort(concurrent, THREADS * PER_THREAD, sizeof(int), compare);
  assert(!memcmp(expected, concurrent, sizeof(expected)));
  errno = E2BIG;
  as_bionic_random_reset();
  assert(errno == E2BIG);
  for (unsigned i = 0; i < 10; ++i)
    assert(draw() == vectors[1][i]);
  assert(errno == E2BIG);
#ifdef AS_RANDOM_REFERENCE
  reference_comparison();
#endif
  puts("native random contracts: PASS (pinned vectors, seeds, aliases, private "
       "state, threads, reset)");
}
